window.OL_I18N = {"lang":"bg","dict":{"meta.appName":"Openline проверка за eSIM съвместимост","meta.searchTitle":"{q} eSIM съвместимост · Openline","ui.skip":"Към съдържанието","ui.brandAria":"Openline — Проверете дали устройството ви е съвместимо","ui.brandSub":"Проверете дали устройството ви е съвместимо","lang.label":"Език","lang.aria":"Смяна на езика","hero.titleHtml":"Поддържа ли устройството ви <span class=\"accent\">eSIM</span>?","hero.tag":"Телефон, таблет, смартчасовник, мобилен рутер — въведете марка или модел и веднага ще ви кажем дали Openline може да се активира на него.","search.placeholder":"Опитайте с „iPhone 18 Pro“, „Galaxy Z Fold8“, „Pixel Watch 5“, „iPad Air“ или номер на модел…","search.aria":"Търсене на марка, модел или номер на модел","search.clear":"Изчистване на търсенето","stats.devices":"устройства","stats.compatible":"съвместими","stats.notCompatible":"несъвместими","stats.brands":"марки","filters.label":"Филтри","filters.summaryAll":"Всички устройства · Всички марки","filters.explain":"Изберете статус на съвместимост и/или една или повече марки. Филтрите се комбинират с търсенето и обновяват списъка в реално време.","filters.compat":"Съвместимост","filters.compatAria":"Филтри за съвместимост","filters.brands":"Марки","filters.brandsAria":"Филтри за марки","filters.clearAll":"Изчистване на всички","filters.compatOnly":"Само съвместими","filters.notCompatOnly":"Само несъвместими","filters.allStatuses":"Всички статуси","filters.nBrands":{"one":"{n} марка","other":"{n} марки"},"filters.matchHtml":{"one":"<strong>{n}</strong> съвпадащо устройство","other":"<strong>{n}</strong> съвпадащи устройства"},"cat.count":{"one":"{n} устройство","other":"{n} устройства"},"results.all":"Всички устройства","results.matching":"Съвпадащи устройства","results.ofTotalHtml":"<strong>{n}</strong> от {total}","results.totalHtml":"общо <strong>{n}</strong>","results.showingFirst":" · показани са първите {max}","legend.ok":"Поддържа eSIM","legend.err":"Само физическа SIM","status.ok":"Съвместимо","status.no":"Несъвместимо","status.okAria":"Съвместимо с eSIM","status.noAria":"Несъвместимо с eSIM","note.caveatAria":"Регионална особеност: {note}","popover.aria":"Регионална особеност","popover.close":"Затваряне","empty.noMatchTitle":"Няма точно съвпадение.","empty.noMatchBodyHtml":"Опитайте само с марката (напр. <em>Samsung</em>) или с точния номер на модела (напр. <em>SM-S921B</em>). Ако устройството ви е излязло след 2021 г. и е купено извън континентален Китай, шансът да поддържа eSIM е много голям.","empty.bothTitle":"Няма устройства, отговарящи едновременно на търсенето и филтрите.","empty.bothBodyHtml":{"one":"Търсенето ви за <em>{q}</em> намира общо <strong>{n}</strong> устройство, но то не отговаря на избраните филтри. Може би филтрите са причината?","other":"Търсенето ви за <em>{q}</em> намира общо <strong>{n}</strong> устройства, но нито едно от тях не отговаря на избраните филтри. Може би филтрите са причината?"},"empty.filtersTitle":"Няма устройства, отговарящи на филтрите.","empty.filtersBody":"Опитайте да разхлабите филтрите — комбинирането на редки статуси на съвместимост с малко на брой марки може да не даде резултати.","empty.nothing":"Все още няма нищо тук.","empty.resetFilters":"Нулиране на филтрите","empty.clearSearch":"Изчистване на търсенето","footer.privacy":"Поверителност","footer.terms":"Условия","footer.socialAria":"Openline в социалните мрежи","footer.onNetwork":"Openline в {network}","footer.handleOnNetwork":"@askopenline в {network}","footer.indexedHtml":"<b id=\"footer-total\">{n}</b> индексирани устройства","region.US":"САЩ","region.HK":"Хонконг","region.CN":"континентален Китай","region.KR":"Южна Корея","region.JP":"Япония","region.AU":"Австралия","region.TW":"Тайван","region.SEA":"Югоизточна Азия","region.EU":"Европейски съюз","region.IN":"Индия","region.UK":"Обединено кралство","exp.carrierWatch":"Смартчасовниците с мобилна връзка получават своята eSIM чрез оператор, с план за часовник, настроен от приложението на свързания телефон (Apple Watch, Galaxy Wearable, Pixel Watch). QR кодове за телефони или туристически eSIM не могат да се инсталират директно на часовника, затова проверете дали операторът ви предлага план за този модел.","exp.gpsOnly":"Това е версията само с GPS. Тя няма мобилен модем и не може да използва никаква eSIM. Версията GPS + Cellular на същия часовник има различен номер на модела.","exp.cnHkMoDualNano":"iPhone от това поколение, продавани в континентален Китай, Хонконг и Макао, имат два слота за физическа nano-SIM карта и нямат eSIM. Openline не може да се инсталира на тези устройства. Проверете номера на модела в Настройки › Общи › Относно.","exp.cnDualNano":"Версията на този телефон за континентален Китай използва две физически nano-SIM карти и няма eSIM. Моделите, продавани навсякъде другаде, поддържат eSIM. Проверете номера на модела в Настройки › Общи › Относно.","exp.cnLocalRules":"Версията за континентален Китай поддържа eSIM, но китайските оператори активират eSIM само в магазините си след проверка на документ за самоличност, а чуждестранни eSIM профили не могат да се инсталират, докато сте в континентален Китай. Извън Китай туристически eSIM като Openline се инсталират нормално.","exp.esimOnlyUsJpCaGulf":"Устройствата, продавани в САЩ, Канада, Япония, Мексико и страните от Персийския залив, нямат слот за SIM карта и работят само с eSIM. На други места телефонът има и nano-SIM слот, а версиите за континентален Китай може да нямат eSIM. Openline работи на всяка версия, поддържаща eSIM.","exp.noSimTray":"Тази версия няма слот за физическа SIM карта: всяка линия, включително Openline, се добавя като eSIM. Можете да запазите няколко eSIM и да превключвате между тях в Настройки.","exp.iden":"Това устройство работи в iDEN мрежата на Motorola (Nextel / Boost push-to-talk), която беше напълно изключена от Sprint през юни 2013 г. То не може да се свърже с никоя съвременна мобилна мрежа — нито с eSIM, нито по друг начин. Само за музеи или колекционери.","exp.cdmaVerizon":"Това е устройство само за CDMA, създадено за старата 2G/3G CDMA мрежа на Verizon, която беше изключена на 31 декември 2022 г. То няма никакъв SIM слот (нито физически, нито eSIM) — CDMA се автентикира в мрежата чрез ESN/MEID на устройството, а не чрез SIM. Не може да се използва с Openline или с друг съвременен оператор.","exp.cdmaSprint":"Това е CDMA устройство, създадено за старата мрежа на Sprint, която T-Mobile изключи окончателно на 31 май 2022 г. По-новите модели на Sprint добавиха LTE/GSM, но по-ранните са само с CDMA и не могат да се свържат с никоя съвременна мрежа — със или без eSIM.","exp.sunset":"Това устройство разчита на 3G или по-стари 4G мрежи, които операторите са изключили (AT&T 3G през февруари 2022 г., T-Mobile през февруари 2022 г., Verizon през декември 2022 г., повечето европейски 3G мрежи до 2025 г.). Дори да има работещ SIM слот, в повечето страни няма мрежа, към която да се свърже.","exp.windowsPhone":"Това устройство работи с Windows Phone (или Windows 10 Mobile), който Microsoft прекрати през 2019 г. — магазинът, актуализациите за сигурност и повечето собствени услуги са спрени. Няма хардуер за eSIM и почти няма поддръжка за съвременни приложения. Неупотребяемо за ежедневна работа.","exp.kaios":"Това е обикновен телефон с KaiOS. Почти никое устройство с KaiOS не поддържа eSIM — те използват физическа SIM (обикновено nano-SIM) и са насочени към пазари на евтини телефони с копчета само с 4G, като Индия (JioPhone) и Африка. Openline не може да се инсталира тук.","exp.telematics":"Това е автомобилен телематичен модул (Tesla, BMW, Audi и др.) с фабрично вградена eSIM, запоена към платката за свързаност на автомобила. eSIM се зарежда от производителя във фабриката и не може да бъде заменена с потребителски профил като Openline. Не подлежи на обслужване от потребителя.","exp.satellite":"Това е сателитен/GPS комуникатор (Garmin inReach, SPOT, Zoleo, Iridium GO), който използва сателитната мрежа на Iridium или Globalstar, а не GSM/LTE. Не може да използва eSIM в обичайния смисъл — свързаността е обвързана със собствен абонамент при производителя на устройството.","exp.medical":"Това е медицинско устройство за спешно известяване (PERS). Мобилният му модем е заключен към доставчика на услугата (Lively, Medical Guardian, Life Alert, Bay Alarm) и работи само с техния абонамент за наблюдение. Не може да инсталира eSIM от трети страни.","exp.rugged":"Това е корпоративно/подсилено устройство на Samsung (серия Galaxy XCover), предназначено за служители на терен — складове, здравеопазване, хотелиерство. То поддържа eSIM, но активирането може да минава през конфигурацията на Samsung Knox MDM на вашия работодател. Openline се инсталира като на всеки потребителски телефон, ако устройството е отключено.","exp.harmony":"Това устройство работи с HarmonyOS (Huawei) без Google Mobile Services. Активирането на eSIM обикновено изисква приложението за услуги на оператори на Huawei EMUI/HarmonyOS; профилите на Openline се зареждат чрез QR код, но активиране през Google Wallet не работи. Устройства, продавани в континентален Китай, може допълнително да отхвърлят международни eSIM профили заради ограничения в китайския фърмуер.","exp.dualEsimOnly":"Този вариант поддържа две eSIM едновременно, но няма слот за физическа SIM карта. Openline работи — просто не можете да го комбинирате с nano-SIM. При някои регионални версии само една eSIM може да е активна в даден момент.","exp.euCarrier":"Някои европейски версии на това устройство, заключени към оператор, са доставени с изключена eSIM на ниво фърмуер. Отключените/глобалните модели поддържат eSIM нормално. Ако активирането е неуспешно, свържете се с първоначалния си оператор.","exp.usCarrier":"Това е версия с марка на американски оператор (AT&T, T-Mobile, Verizon, Sprint) със заключен фърмуер и често със специфична поддръжка на честотни ленти. eSIM може да е изключена или ограничена до профили на оператора с тази марка. Отключените международни устройства от същия модел обикновено работят с Openline; тези с марка на оператор може да не работят.","exp.verizon":"При устройствата Pixel с марка на Verizon eSIM беше изключена при пускането им в мрежата на Verizon. Отключените устройства и тези на други оператори поддържат eSIM нормално.","exp.googleFi":"При това поколение Pixel eSIM беше достъпна в САЩ само чрез Google Fi. Другите оператори използваха само физическа SIM. Глобалните отключени устройства поддържат eSIM навсякъде.","exp.usEsimOnly":"При закупените в САЩ устройства от този iPhone Apple премахна напълно слота за физическа SIM карта — трябва да използвате eSIM. Навсякъде другаде телефонът има слот за физическа SIM освен eSIM. Openline работи и в двата случая.","exp.cnOnly":"Това устройство се доставя с фърмуер за вътрешния пазар на Китай. Поддръжката на eSIM е налична на хартия, но международните профили често не успяват да се активират извън континентален Китай. Ако планирате да пътувате, проверете активирането на eSIM при продавача преди покупка.","exp.jpDomestic":"Телефоните с марка на японски оператори (NTT DoCoMo, au, SoftBank, Rakuten) обикновено са заключени към честотния план на Япония. Хардуерът за eSIM работи в Япония; активирането в чужбина зависи от припокриването на честотните ленти с местните мрежи.","exp.regionLocked":"Активирането на eSIM на това устройство е заключено по региони на ниво фърмуер. То приема само eSIM профили от оператори в държавата/региона, където е продадено.","exp.krOnly":"Този модел се продава само в Южна Корея и използва честотните ленти на KT/SKT/LGU+. Хардуер за eSIM има, но активирането в чужбина не е надеждно.","exp.foldable":"Това е сгъваемо устройство — eSIM е налична, но имайте предвид, че някои сгъваеми варианти, продавани в Китай, нямат поддръжка за международна eSIM. Уверете се, че кодът на модела отговаря на глобалния SKU.","exp.hotspot":"Това е преносим Wi-Fi рутер / MiFi, а не телефон. Той приема eSIM, за да споделя мобилни данни с другите ви устройства. Openline се зарежда по същия начин като на телефон.","exp.simTrayOnly":"Това устройство има мобилен модем, но приема само физическа nano-SIM или micro-SIM карта — няма eSIM чип. Не можете да инсталирате Openline като eSIM тук; ще ви трябва план с физическа SIM карта.","exp.wifiOnly":"Този вариант е само с Wi-Fi — няма мобилен модем. На него не може да се инсталира никаква eSIM. Потърсете версията с LTE / 5G / Cellular на същия модел.","exp.ereader":"Това е електронен четец с фабрично вграден мобилен модем, обвързан с безплатния план за данни на производителя (Amazon Whispernet, B&N nook и др.). eSIM/SIM не може да се зарежда от потребителя — не можете да инсталирате профил на Openline.","exp.cellularEsimOnly":"Този вариант има мобилна връзка само чрез eSIM — на устройството няма слот за физическа SIM. Openline се инсталира директно чрез QR код.","exp.unverifiedVariant":"Нашите данни свързват този код на модел с повече от едно семейство продукти. Това обикновено означава, че Apple/Samsung/Google са използвали повторно вътрешен номер през различни поколения или че регионален SKU е преименуван. Openline би трябвало да работи, но ако номерът на модела на кутията не съвпада с устройството, което разглеждате, проверете при производителя преди покупка.","exp.crossBrand":"Този код на модел се среща и при устройство на друга марка (Vivo/iQOO, Xiaomi/POCO, Nokia/HMD, Nubia/ZTE и др.). Обикновено това са свързани марки — хардуерът често е идентичен, понякога под друга марка — но поддръжката на eSIM и сертификацията от оператори може да се различават между двете марки. Проверете по действителната търговска опаковка на устройството си.","exp.modelUnverified":"Нямаме надежден номер на модел/част за това устройство — обикновено защото е носимо устройство, автомобилен телематичен модул, мобилен рутер или аксесоар, чийто SKU не е публично достъпен. Поддръжката на eSIM е в спецификацията на производителя, но Openline не може да съпостави конкретен хардуерен код, за да гарантира съвместимост. Проверете при производителя, преди да разчитате на нея.","exp.ambiguous":"Името на продукта тук е много кратко („13“, „F7“, „M6“…) и лесно може да се обърка с модели със същия номер от други марки или поколения. Проверете марката и кода на модела на устройството си, за да сте сигурни, че записът съответства на вашето устройство.","exp.cnFirmware":"Това устройство се доставя с фърмуер за вътрешния пазар на Китай. Хардуерът за eSIM е наличен, но китайският фърмуер често блокира активирането на международни eSIM профили. Ако смятате да използвате Openline извън континентален Китай, уверете се преди покупка при продавача, че фърмуерът не е заключен по региони.","exp.regionExcluded":"Устройствата от този модел, продавани в следните региони, нямат хардуер за eSIM, така че работи само слотът за физическа SIM: {regions}. Навсякъде другаде eSIM се поддържа и Openline ще се активира нормално. Ако сте го купили в чужбина или от вносител на сива пазарна територия, проверете номера на модела в списъка на производителя.","note.3G free":"Без 3G","note.3G/4G":"3G/4G","note.AU/JP/TW excluded":"Без AU/JP/TW","note.Ambiguous name":"Неясно име","note.CDMA":"CDMA","note.CN firmware":"CN фърмуер","note.CN/HK excluded":"Без CN/HK","note.CN/HK/MO: dual nano-SIM":"CN/HK/MO: две nano-SIM","note.CN/IN":"CN/IN","note.CN/IN dual-eSIM only":"CN/IN: само две eSIM","note.CN: dual nano-SIM":"CN: две nano-SIM","note.CN: local eSIM rules":"CN: местни eSIM правила","note.Carrier watch plan":"План за часовник от оператор","note.Cross-brand model code":"Код от друга марка","note.E-reader":"Електронен четец","note.Enterprise rugged":"Корпоративно подсилено","note.Foldable":"Сгъваемо","note.GPS only":"Само GPS","note.GPS/satellite tracker":"GPS/сателитен тракер","note.Google Fi/US only":"Само Google Fi/US","note.HarmonyOS":"HarmonyOS","note.JP domestic band lock":"JP: заключени честоти","note.KR only":"Само KR","note.KR/CN":"KR/CN","note.KaiOS feature phone":"Телефон с копчета, KaiOS","note.Medical alert":"Медицинско известяване","note.Mobile hotspot":"Мобилен рутер","note.Model code unverified":"Непотвърден код на модел","note.Nextel/Boost":"Nextel/Boost","note.No eSIM hardware":"Няма хардуер за eSIM","note.No eSIM in most regions":"Без eSIM в повечето региони","note.Not on Verizon/Sprint":"Не работи с Verizon/Sprint","note.SEA excluded":"Без SEA","note.SIM tray only":"Само слот за SIM","note.Sprint":"Sprint","note.US carrier variant":"Версия за US оператор","note.US model excluded":"Без модела за US","note.US variant excluded":"Без версията за US","note.US/HK excluded":"Без US/HK","note.US/JP: eSIM ok":"US/JP: eSIM работи","note.US: eSIM only":"US: само eSIM","note.Unverified variant":"Непотвърден вариант","note.Vehicle telematics":"Автомобилна телематика","note.Verizon":"Verizon","note.Verizon US no eSIM":"Verizon US: без eSIM","note.Verizon-only 5G":"5G само за Verizon","note.Wi-Fi + Cellular only":"Само Wi-Fi + Cellular","note.Wi-Fi + free 4G":"Wi-Fi + безплатен 4G","note.Wi-Fi only":"Само Wi-Fi","note.Wi-Fi only in most regions":"Само Wi-Fi в повечето региони","note.Wi-Fi/3G":"Wi-Fi/3G","note.Windows Phone":"Windows Phone","note.deprecated":"остаряло","note.dual-eSIM in EU":"Две eSIM в EU","note.eSIM only":"Само eSIM","note.eSIM only (no SIM tray)":"Само eSIM (без SIM слот)","note.eSIM only in US/JP/CA/Gulf":"Само eSIM в US/JP/CA/Gulf","note.eSIM only via Google Fi":"eSIM само през Google Fi","note.iDEN":"iDEN","note.sunset":"изключена мрежа"}};
